#!/usr/bin/env python3\n\"\"\"\nHealth Monitor for Air-Gapped RAG Worker\nMonitors worker health and publishes metrics to CloudWatch\n\"\"\"\n\nimport os\nimport sys\nimport time\nimport json\nimport logging\nimport signal\nimport threading\nfrom datetime import datetime, timedelta\nfrom typing import Dict, Any, Optional\n\nimport boto3\nfrom botocore.exceptions import ClientError\n\n# Add src directory to path\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'src'))\n\nfrom ai_inference.core.config import get_config, WorkerConfig\n\nclass HealthMonitor:\n    \"\"\"Monitors RAG worker health and publishes metrics.\"\"\"\n    \n    def __init__(self, environment: str = \"dev\"):\n        self.config = get_config(environment)\n        self.environment = environment\n        self.logger = self._setup_logging()\n        self.session = boto3.Session(region_name=self.config.aws_region)\n        self.cloudwatch = self.session.client(\"cloudwatch\")\n        self.sqs = self.session.client(\"sqs\")\n        self.ssm = self.session.client(\"ssm\")\n        self.running = True\n        self._setup_signal_handlers()\n    \n    def _setup_logging(self) -> logging.Logger:\n        \"\"\"Setup logging for health monitor.\"\"\"\n        logger = logging.getLogger(\"RAG-HealthMonitor\")\n        logger.setLevel(logging.INFO)\n        \n        formatter = logging.Formatter('%(asctime)s [%(levelname)s] %(name)s: %(message)s')\n        handler = logging.StreamHandler()\n        handler.setFormatter(formatter)\n        logger.addHandler(handler)\n        \n        return logger\n    \n    def _setup_signal_handlers(self):\n        \"\"\"Setup signal handlers for graceful shutdown.\"\"\"\n        def signal_handler(signum, frame):\n            self.logger.info(f\"Received signal {signum}, shutting down...\")\n            self.running = False\n        \n        signal.signal(signal.SIGTERM, signal_handler)\n        signal.signal(signal.SIGINT, signal_handler)\n    \n    def check_worker_process(self) -> bool:\n        \"\"\"Check if worker process is running.\"\"\"\n        try:\n            # Check if systemd service is active\n            import subprocess\n            result = subprocess.run(\n                [\"systemctl\", \"is-active\", \"rag-worker\"],\n                capture_output=True,\n                text=True\n            )\n            return result.returncode == 0 and result.stdout.strip() == \"active\"\n        except Exception as e:\n            self.logger.warning(f\"Could not check worker process: {e}\")\n            return False\n    \n    def check_queue_health(self) -> Dict[str, Any]:\n        \"\"\"Check SQS queue health metrics.\"\"\"\n        try:\n            # Get queue attributes\n            response = self.sqs.get_queue_attributes(\n                QueueUrl=self.config.queue_url,\n                AttributeNames=[\n                    'ApproximateNumberOfMessages',\n                    'ApproximateNumberOfMessagesNotVisible',\n                    'ApproximateNumberOfMessagesDelayed'\n                ]\n            )\n            \n            attrs = response['Attributes']\n            return {\n                'messages_available': int(attrs.get('ApproximateNumberOfMessages', 0)),\n                'messages_in_flight': int(attrs.get('ApproximateNumberOfMessagesNotVisible', 0)),\n                'messages_delayed': int(attrs.get('ApproximateNumberOfMessagesDelayed', 0)),\n                'healthy': True\n            }\n        except Exception as e:\n            self.logger.error(f\"Queue health check failed: {e}\")\n            return {\n                'messages_available': 0,\n                'messages_in_flight': 0,\n                'messages_delayed': 0,\n                'healthy': False,\n                'error': str(e)\n            }\n    \n    def check_dlq_health(self) -> Dict[str, Any]:\n        \"\"\"Check dead letter queue health.\"\"\"\n        try:\n            response = self.sqs.get_queue_attributes(\n                QueueUrl=self.config.dlq_url,\n                AttributeNames=['ApproximateNumberOfMessages']\n            )\n            \n            dlq_count = int(response['Attributes'].get('ApproximateNumberOfMessages', 0))\n            return {\n                'messages_in_dlq': dlq_count,\n                'healthy': dlq_count == 0,\n                'warning': dlq_count > 0\n            }\n        except Exception as e:\n            self.logger.error(f\"DLQ health check failed: {e}\")\n            return {\n                'messages_in_dlq': -1,\n                'healthy': False,\n                'error': str(e)\n            }\n    \n    def check_kill_switch(self) -> Dict[str, Any]:\n        \"\"\"Check kill switch status.\"\"\"\n        try:\n            response = self.ssm.get_parameter(Name=self.config.ssm_kill_switch)\n            enabled = response['Parameter']['Value'].lower() == 'true'\n            return {\n                'processing_enabled': enabled,\n                'healthy': True\n            }\n        except Exception as e:\n            self.logger.error(f\"Kill switch check failed: {e}\")\n            return {\n                'processing_enabled': False,\n                'healthy': False,\n                'error': str(e)\n            }\n    \n    def check_vllm_connectivity(self) -> Dict[str, Any]:\n        \"\"\"Check vLLM server connectivity.\"\"\"\n        try:\n            import requests\n            response = requests.get(\n                f\"{self.config.vllm_url}/v1/models\",\n                timeout=10\n            )\n            return {\n                'vllm_accessible': response.status_code == 200,\n                'response_time_ms': response.elapsed.total_seconds() * 1000,\n                'healthy': response.status_code == 200\n            }\n        except Exception as e:\n            self.logger.warning(f\"vLLM connectivity check failed: {e}\")\n            return {\n                'vllm_accessible': False,\n                'healthy': False,\n                'error': str(e)\n            }\n    \n    def publish_metrics(self, metrics: Dict[str, Any]):\n        \"\"\"Publish metrics to CloudWatch.\"\"\"\n        try:\n            metric_data = []\n            timestamp = datetime.utcnow()\n            \n            # Worker health metric\n            worker_healthy = (\n                metrics.get('worker_process', {}).get('running', False) and\n                metrics.get('queue', {}).get('healthy', False) and\n                metrics.get('kill_switch', {}).get('healthy', False)\n            )\n            \n            metric_data.append({\n                'MetricName': 'WorkerHealthy',\n                'Value': 1 if worker_healthy else 0,\n                'Unit': 'None',\n                'Timestamp': timestamp,\n                'Dimensions': [\n                    {'Name': 'Environment', 'Value': self.environment}\n                ]\n            })\n            \n            # Queue metrics\n            queue_metrics = metrics.get('queue', {})\n            if 'messages_available' in queue_metrics:\n                metric_data.append({\n                    'MetricName': 'QueueDepth',\n                    'Value': queue_metrics['messages_available'],\n                    'Unit': 'Count',\n                    'Timestamp': timestamp,\n                    'Dimensions': [\n                        {'Name': 'Environment', 'Value': self.environment}\n                    ]\n                })\n            \n            if 'messages_in_flight' in queue_metrics:\n                metric_data.append({\n                    'MetricName': 'MessagesInFlight',\n                    'Value': queue_metrics['messages_in_flight'],\n                    'Unit': 'Count',\n                    'Timestamp': timestamp,\n                    'Dimensions': [\n                        {'Name': 'Environment', 'Value': self.environment}\n                    ]\n                })\n            \n            # DLQ metrics\n            dlq_metrics = metrics.get('dlq', {})\n            if 'messages_in_dlq' in dlq_metrics and dlq_metrics['messages_in_dlq'] >= 0:\n                metric_data.append({\n                    'MetricName': 'DeadLetterQueueDepth',\n                    'Value': dlq_metrics['messages_in_dlq'],\n                    'Unit': 'Count',\n                    'Timestamp': timestamp,\n                    'Dimensions': [\n                        {'Name': 'Environment', 'Value': self.environment}\n                    ]\n                })\n            \n            # vLLM metrics\n            vllm_metrics = metrics.get('vllm', {})\n            if 'vllm_accessible' in vllm_metrics:\n                metric_data.append({\n                    'MetricName': 'VLLMAccessible',\n                    'Value': 1 if vllm_metrics['vllm_accessible'] else 0,\n                    'Unit': 'None',\n                    'Timestamp': timestamp,\n                    'Dimensions': [\n                        {'Name': 'Environment', 'Value': self.environment}\n                    ]\n                })\n            \n            if 'response_time_ms' in vllm_metrics:\n                metric_data.append({\n                    'MetricName': 'VLLMResponseTime',\n                    'Value': vllm_metrics['response_time_ms'],\n                    'Unit': 'Milliseconds',\n                    'Timestamp': timestamp,\n                    'Dimensions': [\n                        {'Name': 'Environment', 'Value': self.environment}\n                    ]\n                })\n            \n            # Publish metrics in batches (CloudWatch limit is 20 per call)\n            for i in range(0, len(metric_data), 20):\n                batch = metric_data[i:i+20]\n                self.cloudwatch.put_metric_data(\n                    Namespace='AirGappedRAG',\n                    MetricData=batch\n                )\n            \n            self.logger.debug(f\"Published {len(metric_data)} metrics to CloudWatch\")\n            \n        except Exception as e:\n            self.logger.error(f\"Failed to publish metrics: {e}\")\n    \n    def run_health_checks(self) -> Dict[str, Any]:\n        \"\"\"Run all health checks and return results.\"\"\"\n        self.logger.debug(\"Running health checks...\")\n        \n        metrics = {\n            'timestamp': datetime.utcnow().isoformat(),\n            'environment': self.environment,\n            'worker_process': {\n                'running': self.check_worker_process()\n            },\n            'queue': self.check_queue_health(),\n            'dlq': self.check_dlq_health(),\n            'kill_switch': self.check_kill_switch(),\n            'vllm': self.check_vllm_connectivity()\n        }\n        \n        # Calculate overall health\n        health_checks = [\n            metrics['worker_process']['running'],\n            metrics['queue']['healthy'],\n            metrics['kill_switch']['healthy']\n        ]\n        \n        metrics['overall_healthy'] = all(health_checks)\n        \n        return metrics\n    \n    def run(self):\n        \"\"\"Main monitoring loop.\"\"\"\n        self.logger.info(f\"Health monitor starting for environment: {self.environment}\")\n        \n        while self.running:\n            try:\n                # Run health checks\n                metrics = self.run_health_checks()\n                \n                # Log health status\n                if metrics['overall_healthy']:\n                    self.logger.info(\"System healthy\")\n                else:\n                    self.logger.warning(f\"System unhealthy: {json.dumps(metrics, indent=2)}\")\n                \n                # Publish metrics to CloudWatch\n                if self.config.metrics_enabled:\n                    self.publish_metrics(metrics)\n                \n                # Wait for next check\n                time.sleep(self.config.worker_health_check_interval)\n                \n            except KeyboardInterrupt:\n                self.logger.info(\"Keyboard interrupt received\")\n                break\n            except Exception as e:\n                self.logger.error(f\"Unexpected error in health monitor: {e}\")\n                time.sleep(10)  # Brief pause before retrying\n        \n        self.logger.info(\"Health monitor shutting down\")\n\ndef main():\n    \"\"\"Main entry point.\"\"\"\n    import argparse\n    \n    parser = argparse.ArgumentParser(description=\"Air-Gapped RAG Health Monitor\")\n    parser.add_argument(\n        \"environment\",\n        nargs=\"?\",\n        default=os.getenv(\"ENVIRONMENT\", \"dev\"),\n        choices=[\"dev\", \"staging\", \"prod\"],\n        help=\"Environment to monitor (default: dev)\"\n    )\n    parser.add_argument(\n        \"--once\",\n        action=\"store_true\",\n        help=\"Run health checks once and exit\"\n    )\n    \n    args = parser.parse_args()\n    \n    try:\n        monitor = HealthMonitor(args.environment)\n        \n        if args.once:\n            # Run once and print results\n            metrics = monitor.run_health_checks()\n            print(json.dumps(metrics, indent=2))\n            sys.exit(0 if metrics['overall_healthy'] else 1)\n        else:\n            # Run continuous monitoring\n            monitor.run()\n            \n    except KeyboardInterrupt:\n        print(\"\\nShutdown requested by user\")\n    except Exception as e:\n        print(f\"Fatal error: {e}\")\n        sys.exit(1)\n\nif __name__ == \"__main__\":\n    main()